CREATE OR REPLACE FUNCTION mission_creation_owner.bind_human_arena(p_master uuid, p_encounter uuid, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e mission_creation_owner.human_encounters;b mission_generic_owner.run_bindings;m public.master_v2_sessions;
 t combat_spatial.arena_templates;src jsonb;pid uuid;claim uuid;iid uuid;policy text;chosen boolean;
 a record;slot record;radius numeric;principal uuid;
begin
 select * into strict e from mission_creation_owner.human_encounters where encounter_id=p_encounter and master_session_id=p_master;
 if NOT mission_generic_owner.regia_entry_permit_valid_v1(p_master,p_request) then
  perform mission_creation_owner.human_assert(p_master);
 end if;
 select * into strict m from public.master_v2_sessions where id=p_master for update;
 select * into strict b from mission_generic_owner.run_bindings where master_session_id=p_master;
 src:=mission_creation_owner.arena_for_step(p_master,e.step_key);
 select * into strict t from combat_spatial.arena_templates
 where template_key=src->>'template_key' and template_version=(src->>'template_version')::integer and status='ready' for share;
 perform 1 from combat_spatial.arena_slots where template_key=t.template_key and template_version=t.template_version order by slot_key for share;
 perform 1 from combat_spatial.arena_objects where template_key=t.template_key and template_version=t.template_version order by object_key for share;
 if src->>'zone_key'<>'arena' or src->>'catalog_sha256' is distinct from combat_panel_private.universal_arena_hash(t.template_key,t.template_version)
 or t.geometry_hash is distinct from combat_spatial.geometry_fingerprint(t.template_key,t.template_version)
 or combat_spatial.template_errors(t.template_key,t.template_version)<>'[]'::jsonb
 then raise exception 'MG_ARENA_FROZEN_CATALOG_DRIFT' using errcode='40001';end if;
 if exists(select 1 from combat_spatial.arena_instances where encounter_id=p_encounter)
 or exists(select 1 from public.combat_v2_declarations d join public.combat_v2_rounds r on r.id=d.round_id where r.session_id=p_encounter)
 then raise exception 'MG_ARENA_ALREADY_BOUND_OR_DECLARED';end if;
 policy:=case when (select is_test from public.locations where id=m.location_id)
 then 'staff_test_no_persistent_resources_v1' else 'master_game_resources_v1' end;
 pid:=mission_ai_service_owner.uuid5(p_encounter,'generic-arena-profile');
 claim:=mission_ai_service_owner.uuid5(p_encounter,'generic-arena-claim');
 iid:=mission_ai_service_owner.uuid5(p_encounter,'generic-arena-instance');
 insert into combat_panel_private.master_panel_sessions(master_session_id,location_id,policy_id)
 values(p_master,m.location_id,policy) on conflict(master_session_id) do nothing;
 if not exists(select 1 from combat_panel_private.master_panel_sessions where master_session_id=p_master and location_id=m.location_id and policy_id=policy)
 then raise exception 'MG_ARENA_PANEL_POLICY_CONFLICT';end if;
 insert into combat_panel_private.master_scene_profiles(id,location_id,label,template_key,template_version,profile_version,geometry_fingerprint,policy_id,visibility_mode,enabled)
 values(pid,m.location_id,'Arena missione',t.template_key,t.template_version,1,t.geometry_hash,policy,'participants',true);
 insert into combat_panel_private.master_scene_claims(id,profile_id,profile_version,master_session_id,encounter_id,
 template_key,template_version,authority_principal_id,authority_control_version,geometry_fingerprint,roster_fingerprint,policy_id,visibility_mode)
 values(claim,pid,1,p_master,p_encounter,t.template_key,t.template_version,m.master_user,m.control_version,
 t.geometry_hash,combat_panel_private.master_roster_fingerprint(p_encounter),policy,'participants');
 insert into combat_spatial.arena_instances(instance_id,master_session_id,encounter_id,binding_id,template_key,template_version,map_version,state,context_source,panel_claim_id)
 values(iid,p_master,p_encounter,null,t.template_key,t.template_version,1,'open','panel_master',claim);
 -- Le opzioni e le collisioni derivano dal catalogo server; nessuna coordinata IA/client.
 for a in select * from public.combat_v2_actors where session_id=p_encounter and state='attivo' order by actor_kind,id loop
  radius:=t.actor_radius_m;chosen:=false;
  for slot in select * from combat_spatial.arena_slots where template_key=t.template_key and template_version=t.template_version
  and actor_kind=upper(a.actor_kind) order by slot_key loop
   if clan_marionettisti_private.scene_slot_legal(t.template_key,t.template_version,round(slot.x_m),round(slot.y_m),radius)
   and not exists(select 1 from combat_spatial.actor_states z where z.instance_id=iid and
   (z.slot_key=slot.slot_key or combat_spatial.distance_m(z.x_m,z.y_m,round(slot.x_m),round(slot.y_m))<=z.footprint_radius_m+radius)) then
    principal:=case when a.actor_kind='pg' then a.controller_user else m.master_user end;
    insert into combat_panel_private.master_placement_options(claim_id,actor_id,slot_key,x_m,y_m,radius_m)
    values(claim,a.id,slot.slot_key,round(slot.x_m),round(slot.y_m),radius);
    insert into combat_spatial.actor_states(instance_id,actor_id,actor_kind,slot_key,controller_principal_id,projection_subject_id,x_m,y_m,footprint_radius_m,body_version,state)
    values(iid,a.id,upper(a.actor_kind),slot.slot_key,principal,gen_random_uuid(),round(slot.x_m),round(slot.y_m),radius,1,'active');
    chosen:=true;exit;
   end if;
  end loop;
  if not chosen then raise exception 'MG_ARENA_LEGAL_SLOTS_INSUFFICIENT' using errcode='22023';end if;
 end loop;
 insert into combat_spatial.viewer_grants(instance_id,viewer_principal_id,subject_actor_id,can_view_map,can_view_objects,grant_version)
 select iid,v.controller_principal_id,z.actor_id,true,true,1 from combat_spatial.actor_states z
 cross join (select distinct controller_principal_id from combat_spatial.actor_states where instance_id=iid) v where z.instance_id=iid;
 insert into combat_spatial.object_states(instance_id,object_key,state,state_version)
 select iid,object_key,case when substitutable then 'available' else 'blocked' end,1 from combat_spatial.arena_objects
 where template_key=t.template_key and template_version=t.template_version;
 for a in select * from combat_spatial.actor_states where instance_id=iid loop
  if combat_spatial.path_first_block_t(iid,a.actor_id,a.x_m,a.y_m,a.x_m,a.y_m,null)<1
  then raise exception 'MG_ARENA_FINAL_OCCUPANCY_INVALID' using errcode='22023';end if;
 end loop;
 return jsonb_build_object('instance_id',iid,'claim_id',claim,'map_version',1);
end $function$

CREATE OR REPLACE FUNCTION mission_creation_owner.general_choose_points(p_points jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare lx integer[]:=array[]::integer[];ly integer[]:=array[]::integer[];
 rx integer[]:=array[]::integer[];ry integer[]:=array[]::integer[];
 ml integer[];mr integer[];pr integer[];ql integer[];vl boolean[];vr boolean[];
 n_l integer;n_r integer;u integer;v integer;u0 integer;head integer;found_v integer;prev_v integer;
 point jsonb;chosen jsonb:='[]'::jsonb;result jsonb;
begin
 for point in select value from jsonb_array_elements(p_points) order by (value->>'y')::integer,(value->>'x')::integer loop
  if mod((point->>'x')::integer+(point->>'y')::integer,2)=0 then
   lx:=array_append(lx,(point->>'x')::integer);ly:=array_append(ly,(point->>'y')::integer);
  else
   rx:=array_append(rx,(point->>'x')::integer);ry:=array_append(ry,(point->>'y')::integer);
  end if;
 end loop;
 n_l:=cardinality(lx);n_r:=cardinality(rx);
 if n_l>=16 or n_r>=16 then
  if n_l>=n_r then
   for u in 1..least(n_l,16) loop chosen:=chosen||jsonb_build_array(jsonb_build_object('x',lx[u],'y',ly[u]));end loop;
  else
   for v in 1..least(n_r,16) loop chosen:=chosen||jsonb_build_array(jsonb_build_object('x',rx[v],'y',ry[v]));end loop;
  end if;
  return (select coalesce(jsonb_agg(value order by (value->>'y')::integer,(value->>'x')::integer),'[]'::jsonb) from jsonb_array_elements(chosen));
 end if;
 -- Qui n_l+n_r <= 30: matching massimo bipartito con cammini aumentanti BFS.
 ml:=array_fill(0,array[n_l]);mr:=array_fill(0,array[n_r]);
 for u0 in 1..n_l loop
  vl:=array_fill(false,array[n_l]);vr:=array_fill(false,array[n_r]);pr:=array_fill(0,array[n_r]);
  ql:=array[u0];vl[u0]:=true;head:=1;found_v:=0;
  while head<=cardinality(ql) and found_v=0 loop
   u:=ql[head];head:=head+1;
   for v in 1..n_r loop
    if not vr[v] and abs(lx[u]-rx[v])+abs(ly[u]-ry[v])=1 then
     vr[v]:=true;pr[v]:=u;
     if mr[v]=0 then found_v:=v;exit;end if;
     if not vl[mr[v]] then vl[mr[v]]:=true;ql:=array_append(ql,mr[v]);end if;
    end if;
   end loop;
  end loop;
  v:=found_v;
  while v<>0 loop
   u:=pr[v];prev_v:=ml[u];ml[u]:=v;mr[v]:=u;v:=prev_v;
  end loop;
 end loop;
 -- Dalle sinistre non accoppiate: cammini alternanti -> complemento della copertura minima.
 vl:=array_fill(false,array[n_l]);vr:=array_fill(false,array[n_r]);ql:=array[]::integer[];
 for u in 1..n_l loop if ml[u]=0 then vl[u]:=true;ql:=array_append(ql,u);end if;end loop;
 head:=1;
 while head<=cardinality(ql) loop
  u:=ql[head];head:=head+1;
  for v in 1..n_r loop
   if not vr[v] and ml[u]<>v and abs(lx[u]-rx[v])+abs(ly[u]-ry[v])=1 then
    vr[v]:=true;
    if mr[v]<>0 and not vl[mr[v]] then vl[mr[v]]:=true;ql:=array_append(ql,mr[v]);end if;
   end if;
  end loop;
 end loop;
 for u in 1..n_l loop if vl[u] then chosen:=chosen||jsonb_build_array(jsonb_build_object('x',lx[u],'y',ly[u]));end if;end loop;
 for v in 1..n_r loop if not vr[v] then chosen:=chosen||jsonb_build_array(jsonb_build_object('x',rx[v],'y',ry[v]));end if;end loop;
 return (select coalesce(jsonb_agg(value order by (value->>'y')::integer,(value->>'x')::integer),'[]'::jsonb)
  from (select value from jsonb_array_elements(chosen) order by (value->>'y')::integer,(value->>'x')::integer limit 16) z);
end $function$

CREATE OR REPLACE FUNCTION mission_creation_owner.general_plan_positions(p_template text, p_version integer, p_pg integer, p_png integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t combat_spatial.arena_templates;h record;point jsonb;all_points jsonb:='[]'::jsonb;
 hints_pg jsonb:='[]'::jsonb;hints_png jsonb:='[]'::jsonb;available jsonb:='[]'::jsonb;
 chosen jsonb:='[]'::jsonb;fallback jsonb;out_pg jsonb;out_png jsonb;
 x integer;y integer;close_to_hint boolean;
begin
 if p_pg not between 0 and 4 or p_png not between 0 and 12 or p_pg+p_png=0 then
  raise exception 'MC_GENERAL_ROSTER_INVALID' using errcode='22023';end if;
 select * into strict t from combat_spatial.arena_templates where template_key=p_template and template_version=p_version
  and contract_version='arena-template/general-v1' and status='ready';
 if combat_spatial.template_errors(p_template,p_version)<>'[]'::jsonb then
  raise exception 'MC_GENERAL_MAP_INVALID' using errcode='22023';end if;
 for y in 1..t.height_m::integer-1 loop
  for x in 1..t.width_m::integer-1 loop
   if clan_marionettisti_private.scene_slot_legal(p_template,p_version,x,y,0.5)
   then all_points:=all_points||jsonb_build_array(jsonb_build_object('x',x,'y',y));end if;
  end loop;
 end loop;
 -- Prima i suggerimenti PG, poi PNG, ma solo se non collidono tra loro.
 for h in select * from combat_spatial.arena_slots where template_key=p_template and template_version=p_version
  order by case actor_kind when 'PG' then 0 else 1 end,slot_key loop
  if (h.actor_kind='PG' and jsonb_array_length(hints_pg)>=p_pg) or
   (h.actor_kind='PNG' and jsonb_array_length(hints_png)>=p_png) then continue;end if;
  x:=h.x_m::integer;y:=h.y_m::integer;
  if not clan_marionettisti_private.scene_slot_legal(p_template,p_version,x,y,0.5)
  or exists(select 1 from jsonb_array_elements(hints_pg||hints_png) z
   where abs((z->>'x')::integer-x)+abs((z->>'y')::integer-y)<=1) then continue;end if;
  point:=jsonb_build_object('x',x,'y',y,'slot_key',h.slot_key);
  if h.actor_kind='PG' then hints_pg:=hints_pg||jsonb_build_array(point);
  else hints_png:=hints_png||jsonb_build_array(point);end if;
 end loop;
 for point in select value from jsonb_array_elements(all_points) loop
  x:=(point->>'x')::integer;y:=(point->>'y')::integer;
  if not exists(select 1 from jsonb_array_elements(hints_pg||hints_png) z
   where abs((z->>'x')::integer-x)+abs((z->>'y')::integer-y)<=1)
  then available:=available||jsonb_build_array(point);end if;
 end loop;
 fallback:=mission_creation_owner.general_choose_points(available);
 if jsonb_array_length(fallback)+jsonb_array_length(hints_pg)+jsonb_array_length(hints_png)<p_pg+p_png then
  -- Nessun suggerimento è obbligatorio: il massimo insieme indipendente decide.
  hints_pg:='[]'::jsonb;hints_png:='[]'::jsonb;
  fallback:=mission_creation_owner.general_choose_points(all_points);
 end if;
 if jsonb_array_length(fallback)<p_pg+p_png-jsonb_array_length(hints_pg)-jsonb_array_length(hints_png)
 then raise exception 'MC_GENERAL_MAP_CAPACITY' using errcode='22023';end if;
 out_pg:=hints_pg;out_png:=hints_png;
 for point in select value from jsonb_array_elements(fallback) loop
  exit when jsonb_array_length(out_pg)>=p_pg and jsonb_array_length(out_png)>=p_png;
  x:=(point->>'x')::integer;y:=(point->>'y')::integer;
  if jsonb_array_length(out_pg)<p_pg then
   out_pg:=out_pg||jsonb_build_array(point||jsonb_build_object('slot_key','AUTO-PG-'||lpad(x::text,2,'0')||'-'||lpad(y::text,2,'0')));
  else
   out_png:=out_png||jsonb_build_array(point||jsonb_build_object('slot_key','AUTO-PNG-'||lpad(x::text,2,'0')||'-'||lpad(y::text,2,'0')));
  end if;
 end loop;
 return out_pg||out_png;
end $function$

